export const RETA_PATH='/guides/retatrutide-uk-guide';
export const COMPARISON_PATH='/future-medicines-comparison';
export const RETA_IMAGE_PATH='/assets/retatrutide-receptor-mechanism-20261102.png';
export const RETA_RELEASE='retatrutide-evidence-20261102';
export function withRetatrutideWorker(original){
 return {...original,async fetch(request,...args){
  const url=new URL(request.url);
  if(!['shiftsometimber.co.uk','www.shiftsometimber.co.uk'].includes(url.hostname)||!['GET','HEAD'].includes(request.method)||!isRetaDocument(url.pathname))return original.fetch(request,...args);
  const response=await original.fetch(request,...args);
  if(response.status!==200||!(response.headers.get('Content-Type')||'').includes('text/html'))return response;
  const headers=new Headers(response.headers);headers.set('X-Shift-Retatrutide-Evidence',RETA_RELEASE);
  for(const key of ['Content-Length','Content-Encoding','ETag','Content-MD5','Digest','Last-Modified'])headers.delete(key);
  return new Response(request.method==='HEAD'?null:await withRetatrutideEvidence(await response.text(),url.pathname),{status:response.status,statusText:response.statusText,headers});
 }};
}
const ORIGIN='https://shiftsometimber.co.uk';
const normalized=path=>path.replace(/\/+$/,'').replace(/\.html$/,'');
export const isRetaDocument=path=>[RETA_PATH,COMPARISON_PATH].includes(normalized(path));
const jsJson=value=>JSON.stringify(value).replace(/</g,'\\u003c');
const plain=value=>value.replace(/<br\s*\/?>/g,' ').replace(/<[^>]+>/g,' ').replace(/\s+/g,' ').trim();
export function retatrutideImage(request){
 if(new URL(request.url).pathname!==RETA_IMAGE_PATH||!['GET','HEAD'].includes(request.method))return null;
 const etag='"'+IMAGE_SHA256+'"',headers={'Content-Type':'image/png','Cache-Control':'public, max-age=31536000, immutable','ETag':etag,'X-Content-Type-Options':'nosniff'};
 if(request.headers.get('If-None-Match')===etag)return new Response(null,{status:304,headers});
 return new Response(request.method==='HEAD'?null:Uint8Array.from(atob(IMAGE_BASE64),x=>x.charCodeAt(0)),{headers});
}
export function renderRetatrutideGuide(){
 const t=evidence.triumph1,z=evidence.triumph2;
 const values={TRANSCEND_ACTIVE:evidence.transcendT2D2.active.toFixed(1),TRANSCEND_COMPARATOR:evidence.transcendT2D2.comparator.toFixed(1),T2_NAUSEA_ACTIVE_DECIMAL:z.nausea[0].toFixed(1),T2_NAUSEA_PLACEBO_DECIMAL:z.nausea[1].toFixed(1),T2_NAUSEA_ACTIVE:z.nausea[0],T2_NAUSEA_PLACEBO:z.nausea[1],T2_DIARRHOEA_ACTIVE:z.diarrhoea[0],T2_DIARRHOEA_PLACEBO:z.diarrhoea[1],T1_ACTIVE:t.treatment.active.toFixed(1),T1_PLACEBO:t.treatment.placebo.toFixed(1),T1_EFFICACY_ACTIVE:t.efficacy.active.toFixed(1),T1_EFFICACY_PLACEBO:t.efficacy.placebo.toFixed(1),T2_ACTIVE:z.activeWeight.toFixed(1),T2_PLACEBO:z.placeboWeight.toFixed(1),T1_ACTIVE_BAR:(t.treatment.active*17.5).toFixed(3),T1_ACTIVE_X:(49+t.treatment.active*17.5).toFixed(3),T1_PLACEBO_BAR:(t.treatment.placebo*17.5).toFixed(3),T1_PLACEBO_X:(49+t.treatment.placebo*17.5).toFixed(3)};
 const html=TEMPLATE.replace(/\[\[([A-Z0-9_]+)\]\]/g,(_,key)=>{if(!(key in values))throw Error('Missing evidence field '+key);return values[key]});
 const script=SCRIPT.replace('__TREATMENT__',jsJson([t.treatment.active,t.treatment.placebo])).replace('__EFFICACY__',jsJson([t.efficacy.active,t.efficacy.placebo]));
 return html.replace('</main>','<script data-retatrutide-chart>'+script+'</script></main>');
}
function rewriteMedicalSchema(html){
 const image={'@type':'ImageObject',url:ORIGIN+RETA_IMAGE_PATH,width:1200,height:820,caption:'Original SHIFT diagram: retatrutide targets GLP-1, GIP and glucagon receptors. Not a product image.'};
 function visit(node){
  if(!node||typeof node!=='object')return node;
  if(Array.isArray(node))return node.map(visit).filter(Boolean);
  const types=[node['@type']].flat();
  if(types.includes('FAQPage'))return null;
  if(types.some(t=>['Article','MedicalWebPage'].includes(t))){
   node={...node,dateModified:evidence.sourceChecked,image,citation:[evidence.authorisationSource,evidence.triumph1.treatment.source,evidence.triumph1.efficacy.source,evidence.triumph2.source,evidence.transcendT2D2.source]};
   node.headline='Retatrutide. What we know. What we don’t.';
   // Source checking and owner approval do not establish a clinical reviewer.
   delete node.reviewedBy;delete node.lastReviewed;
  }
  if(node['@graph'])node={...node,'@graph':visit(node['@graph'])};
  return node;
 }
 return html.replace(/<script\b(?=[^>]*\btype=["']application\/ld\+json["'])[^>]*>([\s\S]*?)<\/script>/gi,(tag,raw)=>{
  try{const updated=visit(JSON.parse(raw));return updated?tag.slice(0,tag.indexOf('>')+1)+jsJson(updated)+'</script>':'';}catch{return tag;}
 });
}
const hex=bytes=>[...new Uint8Array(bytes)].map(x=>x.toString(16).padStart(2,'0')).join('');
export async function withRetatrutideEvidence(html,rawPath){
 const path=normalized(rawPath);
 if(path===COMPARISON_PATH){
  return html.replace('UK-authorised prescription medicine — check the page for current access and product information.','This comparison includes authorised and investigational medicines. Check each option’s dated UK status.').replace('August 2026. Sources and review detail remain in the guide.','Sources and review detail remain in each medicine’s guide.').replace('Updated 26 August 2026','Updated 2 November 2026');
 }
 if(path!==RETA_PATH||html.includes('data-reta-evidence="20261102"'))return html;
 if((html.match(/<main\b/gi)||[]).length!==1)return html;
 let result=html.replace(/<main\b[\s\S]*?<\/main>/i,()=>renderRetatrutideGuide());
 result=rewriteMedicalSchema(result);
 result=result.replace(/<meta\b(?=[^>]*\b(?:name|property)=["'](?:og:image|twitter:image)["'])[^>]*>/gi,tag=>tag.replace(/content=["'][^"']*["']/i,'content="'+ORIGIN+RETA_IMAGE_PATH+'"'));
 result=result.replace(/<meta\b(?=[^>]*\b(?:name|property)=["'](?:og:image:alt|twitter:image:alt)["'])[^>]*>/gi,tag=>tag.replace(/content=["'][^"']*["']/i,'content="Original diagram of retatrutide’s three receptor targets"'));
 result=result.replace(/<meta\b(?=[^>]*\bproperty=["']og:image:height["'])[^>]*>/gi,tag=>tag.replace(/content=["'][^"']*["']/i,'content="820"')).replace(/<meta\b(?=[^>]*\bproperty=["']og:image:type["'])[^>]*>/gi,tag=>tag.replace(/content=["'][^"']*["']/i,'content="image/png"'));
 const match=result.match(/(<style\b[^>]*data-reta-inline-css=["']\/assets\/shift-recovery-v6[^>]*>)([\s\S]*?)(<\/style>)/i);
 if(match&&hex(await crypto.subtle.digest('SHA-256',new TextEncoder().encode(match[2])))===FULL_CSS_SHA256)result=result.replace(match[0],()=>match[1]+RECOVERY_CSS+match[3]);
 return result.replace(/<\/head>/i,'<style data-retatrutide-evidence-style>'+SCOPED_CSS+'</style></head>');
}
const TEMPLATE="<main data-reta-evidence=\"20261102\" id=\"main-content\"><div class=\"rr-shell\"><article id=\"guide\" aria-labelledby=\"guide-title\">\n<section class=\"rr-hero\"><div><p class=\"rr-eyebrow\">Retatrutide · research explained</p><h1 id=\"guide-title\">Retatrutide.<br>What we know.<br><span>What we don’t.</span></h1><p class=\"rr-lead\">The retatrutide research, made easier to understand. What the studies measured, what the headlines leave out and where things stand in the UK.</p><span class=\"rr-pill\">INVESTIGATIONAL · NOT UK-AUTHORISED</span><p class=\"rr-meta\">Primary sources checked 2 November 2026.</p></div><figure class=\"rr-hero-art\"><svg class=\"rr-mechanism\" viewBox=\"0 0 600 410\" role=\"img\" aria-labelledby=\"mech-title mech-desc\">\n <title id=\"mech-title\">One investigational molecule, three receptor targets</title><desc id=\"mech-desc\">Retatrutide acts at GLP-1, GIP and glucagon receptors. The connecting lines show receptor targets, not a ranking of benefits or a map of drug absorption.</desc>\n <defs><radialGradient id=\"glow\"><stop stop-color=\"#707762\" stop-opacity=\".23\"/><stop offset=\"1\" stop-color=\"#707762\" stop-opacity=\"0\"/></radialGradient></defs>\n <circle cx=\"300\" cy=\"205\" r=\"200\" fill=\"url(#glow)\"/>\n <circle cx=\"300\" cy=\"205\" r=\"150\" fill=\"none\" stroke=\"#707762\" stroke-opacity=\".3\" stroke-dasharray=\"3 8\"/>\n <path d=\"M300 190 L165 117 M300 190 L435 117 M300 220 L300 330\" fill=\"none\" stroke=\"#aeb899\" stroke-width=\"2\"/>\n <circle cx=\"300\" cy=\"205\" r=\"62\" fill=\"#e7e3da\"/><text x=\"300\" y=\"200\" text-anchor=\"middle\" fill=\"#050505\" font-size=\"20\" font-weight=\"750\">Retatrutide</text><text x=\"300\" y=\"223\" text-anchor=\"middle\" fill=\"#34372d\" font-size=\"12\">ONE MOLECULE</text>\n <g fill=\"#10120e\" stroke=\"#8e9879\" stroke-width=\"1.5\"><circle cx=\"165\" cy=\"117\" r=\"52\"/><circle cx=\"435\" cy=\"117\" r=\"52\"/><circle cx=\"300\" cy=\"330\" r=\"52\"/></g>\n <g fill=\"#e7e3da\" text-anchor=\"middle\" font-size=\"28\" font-weight=\"650\"><text x=\"165\" y=\"124\">GLP-1</text><text x=\"435\" y=\"124\">GIP</text><text x=\"300\" y=\"337\" font-size=\"24\">Glucagon</text></g>\n <g fill=\"#b5b9ac\" text-anchor=\"middle\" font-size=\"12\"><text x=\"165\" y=\"190\">RECEPTOR</text><text x=\"435\" y=\"190\">RECEPTOR</text><text x=\"300\" y=\"405\">RECEPTOR</text></g></svg><figcaption class=\"rr-caption\">Three receptor targets. The clinical findings still have to do the talking. <a class=\"rr-ref\" href=\"#src-lilly-faq\" aria-label=\"See source: lilly-faq\">Source</a></figcaption></figure></section>\n<div class=\"rr-fact-strip\"><div class=\"rr-fact\"><span class=\"rr-kicker\">UK status</span><strong>Not authorised</strong><p>The latest checked MHRA warning is dated 15 October.</p></div><div class=\"rr-fact\"><span class=\"rr-kicker\">UK release date</span><strong>Not confirmed</strong><p>No verified UK launch date was established in this review.</p></div><div class=\"rr-fact\"><span class=\"rr-kicker\">The useful question</span><strong>What does the evidence say?</strong><p>Read the results beside the study’s limits.</p></div></div>\n<aside class=\"rr-answer\"><span id=\"status\"></span><h2>Is retatrutide available in the UK?</h2><p>Retatrutide remains investigational and is not authorised for UK use. Products sold online are not a substitute for the medicine used in authorised clinical trials. SHIFT’s role here is to explain the research. <a class=\"rr-ref\" href=\"#src-mhra\" aria-label=\"See source: mhra\">Source</a></p></aside>\n<nav class=\"rr-jump\" aria-label=\"Guide contents\"><a href=\"#trial\">The trial, in a chart</a><a href=\"#mechanism\">How it works</a><a href=\"#safety\">Safety beside results</a><a href=\"#uk-pathway\">The UK pathway</a><a href=\"#questions\">Your questions</a><a href=\"#sources\">Primary sources</a></nav>\n\n<section class=\"rr-section\" id=\"trial\"><span id=\"weight\"></span><span id=\"trials\"></span><span id=\"evidence\"></span><p class=\"rr-eyebrow\">Read the numbers properly</p><div class=\"rr-split\"><div class=\"rr-body-copy\"><h2>Behind the headline.</h2><p>TRIUMPH-1 studied adults with obesity without diabetes for 80 weeks. Its peer-reviewed treatment-regimen analysis reported average weight reduction of <strong>[[T1_ACTIVE]]%</strong> in the 12 mg research group, versus <strong>[[T1_PLACEBO]]%</strong> with placebo. <a class=\"rr-ref\" href=\"#src-triumph1\" aria-label=\"See source: triumph1\">Source</a></p><p>That analysis includes outcomes regardless of whether participants stayed on their assigned treatment. An average describes a study group, not what will happen to one person.</p><div class=\"rr-note\"><p><strong>Research labels, not instructions.</strong> The dose identifies the trial group. This guide gives no retatrutide dosing or self-injection advice.</p></div></div><div class=\"rr-paper\"><p class=\"rr-eyebrow\">TRIUMPH-1 · 80 weeks · no diabetes</p><h3>Average body-weight reduction</h3><p class=\"rr-sub\" id=\"analysis-heading\">Treatment-regimen analysis · peer-reviewed</p><div id=\"main-chart\"><svg class=\"rr-chart\" viewBox=\"0 0 620 218\" role=\"img\" aria-label=\"TRIUMPH-1 treatment-regimen analysis at 80 weeks\"><title>TRIUMPH-1 treatment-regimen analysis at 80 weeks</title><desc>Average body-weight reduction: retatrutide 12 mg research group [[T1_ACTIVE]]%; placebo [[T1_PLACEBO]]%. Adults without diabetes. Trial-group dose is an identifier, not instructions for use.</desc><line x1=\"40.0\" y1=\"22\" x2=\"40.0\" y2=\"183\" stroke=\"#d6d2c8\" stroke-width=\"1\"/><text x=\"40.0\" y=\"206\" text-anchor=\"middle\" class=\"rr-axis\">0%</text><line x1=\"127.5\" y1=\"22\" x2=\"127.5\" y2=\"183\" stroke=\"#d6d2c8\" stroke-width=\"1\"/><text x=\"127.5\" y=\"206\" text-anchor=\"middle\" class=\"rr-axis\">5%</text><line x1=\"215.0\" y1=\"22\" x2=\"215.0\" y2=\"183\" stroke=\"#d6d2c8\" stroke-width=\"1\"/><text x=\"215.0\" y=\"206\" text-anchor=\"middle\" class=\"rr-axis\">10%</text><line x1=\"302.5\" y1=\"22\" x2=\"302.5\" y2=\"183\" stroke=\"#d6d2c8\" stroke-width=\"1\"/><text x=\"302.5\" y=\"206\" text-anchor=\"middle\" class=\"rr-axis\">15%</text><line x1=\"390.0\" y1=\"22\" x2=\"390.0\" y2=\"183\" stroke=\"#d6d2c8\" stroke-width=\"1\"/><text x=\"390.0\" y=\"206\" text-anchor=\"middle\" class=\"rr-axis\">20%</text><line x1=\"477.5\" y1=\"22\" x2=\"477.5\" y2=\"183\" stroke=\"#d6d2c8\" stroke-width=\"1\"/><text x=\"477.5\" y=\"206\" text-anchor=\"middle\" class=\"rr-axis\">25%</text><line x1=\"565.0\" y1=\"22\" x2=\"565.0\" y2=\"183\" stroke=\"#d6d2c8\" stroke-width=\"1\"/><text x=\"565.0\" y=\"206\" text-anchor=\"middle\" class=\"rr-axis\">30%</text><text x=\"40\" y=\"28\" class=\"rr-bar-label\">Retatrutide · 12 mg research group</text><rect x=\"40\" y=\"37\" width=\"[[T1_ACTIVE_BAR]]\" height=\"22\" rx=\"3\" fill=\"#707762\"/><text x=\"[[T1_ACTIVE_X]]\" y=\"54\" class=\"rr-bar-value\">[[T1_ACTIVE]]%</text><text x=\"40\" y=\"86\" class=\"rr-bar-label\">Placebo</text><rect x=\"40\" y=\"95\" width=\"[[T1_PLACEBO_BAR]]\" height=\"22\" rx=\"3\" fill=\"#b8b4aa\"/><text x=\"[[T1_PLACEBO_X]]\" y=\"112\" class=\"rr-bar-value\">[[T1_PLACEBO]]%</text></svg></div><div class=\"rr-controls\" role=\"group\" aria-label=\"Choose the analysis\"><button type=\"button\" data-analysis=\"treatment\" aria-pressed=\"true\">Treatment-regimen</button><button type=\"button\" data-analysis=\"efficacy\" aria-pressed=\"false\">Efficacy</button></div><p class=\"rr-chart-caption rr-analysis-note\" id=\"analysis-note\">Includes outcomes regardless of adherence or use of prohibited weight-management treatments. Trial averages are not a personal forecast.</p><details open><summary>Read the numbers without the graphic</summary><table class=\"rr-data-table\"><caption>Both analyses from the same trial, at week 80</caption><thead><tr><th scope=\"col\">Analysis</th><th scope=\"col\">12 mg research group</th><th scope=\"col\">Placebo</th></tr></thead><tbody><tr><th scope=\"row\">Treatment-regimen</th><td>[[T1_ACTIVE]]%</td><td>[[T1_PLACEBO]]%</td></tr><tr><th scope=\"row\">Efficacy</th><td>[[T1_EFFICACY_ACTIVE]]%</td><td>[[T1_EFFICACY_PLACEBO]]%</td></tr></tbody></table></details><p class=\"rr-chart-caption\">Point estimates; uncertainty intervals are not shown. Trial funded by Lilly. The primary paper supports the treatment-regimen figures; the sponsor report supplies the efficacy figures. <a class=\"rr-ref\" href=\"#src-triumph1\" aria-label=\"See source: triumph1\">Source</a> <a class=\"rr-ref\" href=\"#src-triumph1-sponsor\" aria-label=\"See source: triumph1-sponsor\">Source</a></p></div></div>\n<div class=\"rr-latest\"><time datetime=\"2026-10-28\">Latest checked development · 28 October 2026</time><h3>A real direct comparison — with a specific scope.</h3><p class=\"rr-intro\">Lilly’s TRANSCEND-T2D-2 topline report described [[TRANSCEND_ACTIVE]]% average weight loss with the 12 mg retatrutide research group versus [[TRANSCEND_COMPARATOR]]% with Ozempic 2 mg at 80 weeks, using an efficacy analysis. This was an open-label trial in adults with type 2 diabetes. Detailed peer-reviewed results were still to follow in the checked announcement. It is not a comparison with Wegovy or Mounjaro. <a class=\"rr-ref\" href=\"#src-transcend\" aria-label=\"See source: transcend\">Source</a></p></div>\n</section>\n\n<section class=\"rr-section\" id=\"mechanism\"><span id=\"what\"></span><p class=\"rr-eyebrow\">A mechanism is the starting point</p><div class=\"rr-two\"><div><h2>What does “triple agonist” mean?</h2><p class=\"rr-intro\">Retatrutide is one investigational molecule that activates GLP-1, GIP and glucagon receptors. “Triple” identifies its targets; it does not mean three times the benefit. “GLP-3” is an inaccurate nickname. <a class=\"rr-ref\" href=\"#src-lilly-faq\" aria-label=\"See source: lilly-faq\">Source</a></p></div><div class=\"rr-note\" style=\"margin-top:0\"><p><strong>A receptor diagram cannot prove a health outcome.</strong><br>Claims about weight, heart health, liver health or energy expenditure need evidence for that specific outcome. We keep the mechanism separate from what trials have actually measured.</p></div></div></section>\n\n<section class=\"rr-section\" id=\"safety\"><p class=\"rr-eyebrow\">Keep both sides in view</p><div class=\"rr-two\"><div class=\"rr-paper\"><p class=\"rr-eyebrow\">TRIUMPH-2 · a different population</p><h3>Selected safety findings</h3><p class=\"rr-sub\">Adults with obesity / overweight and type 2 diabetes</p><svg class=\"rr-chart\" viewBox=\"0 0 620 218\" role=\"img\" aria-label=\"TRIUMPH-2: participants reporting nausea\"><title>TRIUMPH-2: participants reporting nausea</title><desc>Rounded published safety percentages: 28% in the 12 mg research group and 8% with placebo.</desc><line x1=\"40.0\" y1=\"22\" x2=\"40.0\" y2=\"183\" stroke=\"#d6d2c8\" stroke-width=\"1\"/><text x=\"40.0\" y=\"206\" text-anchor=\"middle\" class=\"rr-axis\">0%</text><line x1=\"171.25\" y1=\"22\" x2=\"171.25\" y2=\"183\" stroke=\"#d6d2c8\" stroke-width=\"1\"/><text x=\"171.25\" y=\"206\" text-anchor=\"middle\" class=\"rr-axis\">10%</text><line x1=\"302.5\" y1=\"22\" x2=\"302.5\" y2=\"183\" stroke=\"#d6d2c8\" stroke-width=\"1\"/><text x=\"302.5\" y=\"206\" text-anchor=\"middle\" class=\"rr-axis\">20%</text><line x1=\"433.75\" y1=\"22\" x2=\"433.75\" y2=\"183\" stroke=\"#d6d2c8\" stroke-width=\"1\"/><text x=\"433.75\" y=\"206\" text-anchor=\"middle\" class=\"rr-axis\">30%</text><line x1=\"565.0\" y1=\"22\" x2=\"565.0\" y2=\"183\" stroke=\"#d6d2c8\" stroke-width=\"1\"/><text x=\"565.0\" y=\"206\" text-anchor=\"middle\" class=\"rr-axis\">40%</text><text x=\"40\" y=\"28\" class=\"rr-bar-label\">Retatrutide · 12 mg research group</text><rect x=\"40\" y=\"37\" width=\"367.500\" height=\"22\" rx=\"3\" fill=\"#707762\"/><text x=\"416.500\" y=\"54\" class=\"rr-bar-value\">[[T2_NAUSEA_ACTIVE_DECIMAL]]%</text><text x=\"40\" y=\"86\" class=\"rr-bar-label\">Placebo</text><rect x=\"40\" y=\"95\" width=\"105.000\" height=\"22\" rx=\"3\" fill=\"#b8b4aa\"/><text x=\"154.000\" y=\"112\" class=\"rr-bar-value\">[[T2_NAUSEA_PLACEBO_DECIMAL]]%</text></svg><table class=\"rr-data-table\"><caption>Participants reporting the event · rounded published percentages</caption><thead><tr><th scope=\"col\">Event</th><th scope=\"col\">12 mg research group</th><th scope=\"col\">Placebo</th></tr></thead><tbody><tr><th scope=\"row\">Nausea</th><td>[[T2_NAUSEA_ACTIVE]]%</td><td>[[T2_NAUSEA_PLACEBO]]%</td></tr><tr><th scope=\"row\">Diarrhoea</th><td>[[T2_DIARRHOEA_ACTIVE]]%</td><td>[[T2_DIARRHOEA_PLACEBO]]%</td></tr></tbody></table><p class=\"rr-chart-caption\">Safety denominators: 286 and 287 respectively. Selected events only; this is not the full safety profile. <a class=\"rr-ref\" href=\"#src-triumph2\" aria-label=\"See source: triumph2\">Source</a></p></div><div class=\"rr-body-copy\"><h2>A result is more than a percentage.</h2><p>In this diabetes trial, the treatment-regimen analysis showed <strong>[[T2_ACTIVE]]%</strong> mean weight reduction versus <strong>[[T2_PLACEBO]]%</strong> with placebo at 80 weeks. It should be read as a separate study, not combined with TRIUMPH-1 into a single expected result. <a class=\"rr-ref\" href=\"#src-triumph2\" aria-label=\"See source: triumph2\">Source</a></p><p>Read safety, treatment discontinuation and follow-up alongside weight change. The trials were funded by the developer. Peer review improves scrutiny; it does not remove uncertainty or establish that the medicine is right for a particular person.</p><div class=\"rr-note\"><p><strong>For a medicine page to earn trust:</strong> show who was studied, how long the study ran, which analysis was used, what happened with the comparator and what remains uncertain.</p></div></div></div></section>\n\n<section class=\"rr-section\" id=\"uk-pathway\"><p class=\"rr-eyebrow\">Evidence, approval and access are separate</p><h2>What would have to happen in the UK?</h2><p class=\"rr-intro\">A positive study is one piece of the picture. These stages should never be collapsed into an invented release date.</p><div class=\"rr-pathway\"><div class=\"rr-path-step rr-active\"><span class=\"rr-number\">01 · EVIDENCE</span><h3>Study results are assessed</h3><p>Published trials and sponsor announcements contribute different types of evidence.</p><span class=\"rr-state\">RESULTS AVAILABLE</span></div><div class=\"rr-path-step\"><span class=\"rr-number\">02 · REGULATION</span><h3>UK authorisation is a separate decision</h3><p>The checked MHRA source says retatrutide is not authorised. A company submission plan is not an approval.</p><span class=\"rr-state\">NO UK AUTHORISATION VERIFIED</span></div><div class=\"rr-path-step\"><span class=\"rr-number\">03 · SUPPLY</span><h3>Licensed supply must be established</h3><p>Approval would not itself confirm a pharmacy’s stock, a launch date or a UK price.</p><span class=\"rr-state\">NO CONFIRMED UK LAUNCH DATE OR PRICE</span></div><div class=\"rr-path-step\"><span class=\"rr-number\">04 · NHS ACCESS</span><h3>NHS decisions follow their own processes</h3><p>Authorisation and NHS funding are different decisions. Some assessment work can run in parallel.</p><span class=\"rr-state\">DO NOT INFER NHS AVAILABILITY</span></div></div><p class=\"rr-small\">These boxes show distinct decisions, not a fixed sequence or a predicted timetable. Regulatory and appraisal work can be aligned while the decisions remain independent. <a class=\"rr-ref\" href=\"#src-mhra\" aria-label=\"See source: mhra\">Source</a> <a class=\"rr-ref\" href=\"#src-uk-access\" aria-label=\"See source: uk-access\">Source</a></p></section>\n\n<section class=\"rr-section rr-faq\" id=\"questions\"><span id=\"faq\"></span><p class=\"rr-eyebrow\">Short answers. Sources close by.</p><h2>The questions people are asking.</h2><details><summary>Is “Reta” the same as retatrutide?</summary><p>It is an informal abbreviation used online. The name on a vial or a seller’s page does not establish that the contents match the investigational medicine used in an authorised trial. <a class=\"rr-ref\" href=\"#src-mhra\" aria-label=\"See source: mhra\">Source</a> <a class=\"rr-ref\" href=\"#src-lilly-faq\" aria-label=\"See source: lilly-faq\">Source</a></p></details><details><summary>Is retatrutide better than Mounjaro or Wegovy?</summary><p>Different trial percentages cannot establish a winner. The populations, time points, analyses and safety findings must match the comparison being made. The latest direct result shown here compares retatrutide with Ozempic 2 mg in type 2 diabetes, not those weight-management products. <a class=\"rr-ref\" href=\"#src-transcend\" aria-label=\"See source: transcend\">Source</a></p></details><details><summary>When will it launch, and what will it cost?</summary><p>This source check did not establish a confirmed UK launch date or UK launch price. Prices advertised by sellers of unauthorised products do not establish either. <a class=\"rr-ref\" href=\"#src-mhra\" aria-label=\"See source: mhra\">Source</a> <a class=\"rr-ref\" href=\"#src-lilly-faq\" aria-label=\"See source: lilly-faq\">Source</a></p></details><details><summary>Can I buy or reserve it through SHIFT?</summary><p>No. This is an evidence guide. SHIFT is not offering retatrutide, accepting reservations or providing a buying route.</p></details><details><summary>Why do the charts show different weight-loss figures?</summary><p>Study populations and analysis methods differ. The chart selector shows two analyses of TRIUMPH-1; the safety section concerns TRIUMPH-2, which included type 2 diabetes. All values remain available in ordinary text and tables. <a class=\"rr-ref\" href=\"#src-triumph1\" aria-label=\"See source: triumph1\">Source</a> <a class=\"rr-ref\" href=\"#src-triumph1-sponsor\" aria-label=\"See source: triumph1-sponsor\">Source</a> <a class=\"rr-ref\" href=\"#src-triumph2\" aria-label=\"See source: triumph2\">Source</a></p></details></section>\n</article><div class=\"rr-retained-context\"><section class=\"rr-reta-section\" id=\"illegal\"><h2>What about “Reta peptides”, pens or vials sold online?</h2><p>The MHRA warns against products sold as retatrutide and describes concerns about unregulated medicines’ quality and safety. A label or seller’s certificate does not establish UK authorisation. <a href=\"#r1\">[1]</a></p><p>Research reporting should not become a shopping guide for an unapproved product. This page therefore contains no seller recommendations, affiliate buying links, preparation instructions or reconstitution calculator. Someone concerned about a product they have used should seek professional advice and can consult the MHRA’s reporting information. <a href=\"#r1\">[1]</a></p></section><section class=\"rr-reta-section\" id=\"cost\"><h2>How much will retatrutide cost in the UK?</h2><p><strong>This review has not verified a UK launch price.</strong> Prices advertised for products sold online do not tell us what an authorised future treatment would cost. A predicted figure is not made more reliable by placing “UK” beside it.</p><p>If a legitimate UK price is announced later, a useful comparison would need the supply duration, formulation, required consultation and any compulsory charges. Until then, there is no defensible price table for this guide to publish.</p></section><section class=\"rr-reta-section\" id=\"nhs\"><h2>Will retatrutide be available on the NHS?</h2><p>No routine NHS retatrutide pathway is established by the sources reviewed here. Authorisation and an NHS access decision are separate questions. The NHS explains that weight-management care can involve lifestyle support, selected medicines and, for some people, specialist assessment or surgery. <a href=\"#r7\">[7]</a></p><p>Do not apply another medicine’s eligibility rules to retatrutide or assume a private launch would mean immediate NHS access. A future answer would need a specific, dated decision for the relevant NHS system.</p></section><section class=\"rr-reta-section\" id=\"availability\"><h2>Is there a confirmed retatrutide UK release date?</h2><p>Lilly’s July announcement describes a planned <strong>US regulatory submission in the first quarter of 2027</strong>. That is a company plan to apply, not an approval or a UK release date. <a href=\"#r5\">[5]</a></p><p>Our update rule is straightforward: report a dated decision once it exists, identify the country and regulator, and explain exactly what changed. A projected study completion, conference presentation or filing must not be rewritten as “available from” a particular month.</p></section><section class=\"rr-reta-section\" id=\"vs-mounjaro\"><h2>Retatrutide versus Mounjaro: what is a fair comparison?</h2><p>Retatrutide and Mounjaro’s active ingredient, tirzepatide, are different molecules. Their receptor profiles differ; that description alone cannot establish which produces a better overall outcome for an individual. <a href=\"#r6\">[6]</a></p><p>A useful comparison should put the population, treatment duration, comparator, analysis method and adverse effects side by side. To make a claim about superiority, look for directly relevant comparative evidence rather than choosing the largest percentages from separate studies. This guide makes no head-to-head superiority claim and is not a recommendation to switch treatment.</p></section><section class=\"rr-reta-section\" id=\"vs-wegovy\"><h2>Retatrutide versus Wegovy: avoid the percentage contest</h2><p>Wegovy’s active ingredient, semaglutide, acts through GLP-1; retatrutide is being studied as a triple receptor agonist. <a href=\"#r6\">[6]</a> The same comparison questions apply: Who was studied, against what, for how long, and with what harms or discontinuations?</p><p>“More receptors” and “a larger result in another trial” are not substitutes for an individual assessment. A research-stage medicine should not be presented as an available replacement for someone’s current care.</p></section><section class=\"rr-reta-section\" id=\"surgery\"><h2>Can a medicine trial be compared with weight-loss surgery?</h2><p>A superficially similar weight percentage does not make two interventions equivalent. Any fair assessment would also need the populations, follow-up, complications, subsequent care and outcomes beyond weight. The NHS describes surgery as a treatment requiring specialist consideration, not simply a percentage target. <a href=\"#r7\">[7]</a></p></section><section class=\"rr-reta-section\" id=\"wait\"><h2>Should I wait for a future medicine?</h2><p>This guide cannot decide what care you need now. Discuss your current concerns with an appropriately qualified health professional rather than treating an uncertain future launch as a personal treatment plan. A useful question is: “What are my appropriate options now, and what would genuinely change that decision later?”</p></section><section class=\"rr-reta-section\" id=\"alternatives\"><h2>Where can I find information about current care?</h2><p>The <a href=\"https://www.nhs.uk/conditions/overweight-and-obesity/\" rel=\"noopener noreferrer\">NHS overview of overweight and obesity</a> explains current approaches and how to seek help. For background reading on hormone pathways, use our <a href=\"/glp1-knowledge-centre\">GLP-1 Knowledge Centre</a>. These are reading routes, not an offer of retatrutide.</p></section><section class=\"rr-reta-section\" id=\"natural\"><h2>What about support without medication?</h2><p>The NHS includes eating, activity and behavioural support within weight-management care. <a href=\"#r7\">[7]</a> Discuss what is appropriate and sustainable for your circumstances. “Medication-free” does not need to mean doing everything alone, and reading research does not commit you to taking a medicine.</p></section><section class=\"rr-reta-section\" id=\"prescriber-questions\"><h2>Questions worth asking before believing a headline</h2><ul><li>Does the source refer to retatrutide itself, or a different medicine or combination?</li><li>Is this a regulator’s decision, an original paper, a sponsor announcement or someone else’s interpretation?</li><li>Are benefits and adverse effects reported for the same population and follow-up?</li><li>Are trial completers being presented as though they represent everyone who started?</li><li>Does a claim about men have relevant sex-specific evidence? Inclusion of men in a trial is not proof of a benefit unique to men.</li><li>Is an article explaining research, or quietly directing me towards a seller?</li></ul><p>For context, 51.8% of participants in the published Phase 2 obesity trial were men. That does not make it a men-only trial or establish a male-specific treatment recommendation. <a href=\"#r2\">[2]</a></p></section><section class=\"rr-reta-section\" id=\"shift\"><h2>The SHIFT take</h2><div class=\"rr-reta-status\"><p><strong>Our interpretation:</strong> the useful story is not just the largest weight-loss percentage. It is whether the evidence becomes strong enough to answer questions about benefit, tolerability, day-to-day function and appropriate access.</p><p>For our readers, we would keep asking what a finding changes in real life—and what it does not. Good information should leave you better equipped to question a claim, not more pressured to buy something. We will distinguish what a source reports from what we infer, and leave an unanswered question unanswered rather than invent certainty.</p></div></section><section class=\"rr-reta-section\" id=\"print\"><h2>A short checklist to keep</h2><ul><li>Check UK status at the regulator source.</li><li>Read trial benefits and adverse effects together.</li><li>Identify the population, duration and analysis.</li><li>Do not confuse a submission plan with a launch.</li><li>Take individual treatment questions to a qualified professional.</li></ul><button class=\"rr-btn\" type=\"button\" onclick=\"window.print()\">Print or save this guide</button></section></div><section class=\"rr-section\" id=\"sources\"><p class=\"rr-eyebrow\">Evidence register</p><h2>Sources stay close.</h2><p class=\"rr-intro\">Selected primary sources checked on 2 November 2026.</p><ol class=\"rr-source-list\"><li id=\"src-uk-access\"><a href=\"https://www.gov.uk/government/publications/get-medicines-to-nhs-patients-earlier-via-the-mhra-nice-aligned-pathway/get-medicines-to-nhs-patients-earlier-via-the-mhra-nice-aligned-pathway\" target=\"_blank\" rel=\"noopener\">MHRA / NICE · distinct decisions, aligned assessment</a><span class=\"rr-source-date\">Updated 9 April 2026</span><p>Primary process guidance. Regulatory and health-technology-assessment decisions remain independent even when their assessments and publication dates are aligned.</p></li><li id=\"src-mhra\"><a href=\"https://www.gov.uk/government/news/counterfeit-weight-loss-pens-worth-2-million-seized-by-mhra-and-west-mids-police\" target=\"_blank\" rel=\"noopener\">MHRA · UK status and unauthorised products</a><span class=\"rr-source-date\">15 October 2026</span><p>Regulator. Confirms retatrutide is not UK-authorised; distinguishes legitimate trials from products sold online.</p></li><li id=\"src-lilly-faq\"><a href=\"https://www.lilly.com/news/stories/what-to-know-about-retatrutide\" target=\"_blank\" rel=\"noopener\">Lilly · What to know about retatrutide</a><span class=\"rr-source-date\">Updated October 2026</span><p>Manufacturer information. Mechanism, development status and the distinction between retatrutide and the informal term GLP-3.</p></li><li id=\"src-triumph1\"><a href=\"https://www.nejm.org/doi/full/10.1056/NEJMoa2604169\" target=\"_blank\" rel=\"noopener\">TRIUMPH-1 · peer-reviewed Phase 3 obesity study</a><span class=\"rr-source-date\">29 September 2026</span><p>Randomised trial; 2,339 participants without diabetes. The treatment-regimen analysis is used for the primary chart. Funded by Lilly.</p></li><li id=\"src-triumph1-sponsor\"><a href=\"https://investor.lilly.com/news-releases/news-release-details/lillys-triple-agonist-retatrutide-delivered-powerful-weight-loss\" target=\"_blank\" rel=\"noopener\">TRIUMPH-1 · sponsor announcement and alternative analysis</a><span class=\"rr-source-date\">21 May 2026</span><p>Manufacturer report. Provides the [[T1_EFFICACY_ACTIVE]]% versus [[T1_EFFICACY_PLACEBO]]% efficacy analysis alongside the [[T1_ACTIVE]]% versus [[T1_PLACEBO]]% treatment-regimen analysis. These are different questions within one trial.</p></li><li id=\"src-triumph2\"><a href=\"https://pubmed.ncbi.nlm.nih.gov/42810372/\" target=\"_blank\" rel=\"noopener\">TRIUMPH-2 · peer-reviewed Phase 3 diabetes study</a><span class=\"rr-source-date\">Online 29 September 2026</span><p>The Lancet, DOI 10.1016/S0140-6736(26)01861-1. Randomised trial in 1,152 adults with obesity/overweight and type 2 diabetes. Funded by Lilly. Safety figures below are selected, rounded results.</p></li><li id=\"src-transcend\"><a href=\"https://lilly.gcs-web.com/news-releases/news-release-details/lillys-retatrutide-delivered-greater-a1c-reduction-and-more\" target=\"_blank\" rel=\"noopener\">TRANSCEND-T2D-2 · latest direct comparison</a><span class=\"rr-source-date\">28 October 2026</span><p>Manufacturer topline report, not a peer-reviewed paper in this review. Open-label trial in type 2 diabetes; comparator was Ozempic 2 mg. It does not settle a comparison with Mounjaro or Wegovy.</p></li></ol><details><summary>Earlier sources supporting the retained context</summary><ol class=\"rr-reta-source\"><li id=\"r1\"><a href=\"https://www.gov.uk/government/news/no-summer-shortcut-for-safe-weight-loss\" rel=\"noopener noreferrer\">MHRA: UK retatrutide warning, 24 July 2026</a>.</li><li id=\"r2\"><a href=\"https://www.nejm.org/doi/abs/10.1056/NEJMoa2301972\" rel=\"noopener noreferrer\">Jastreboff and colleagues: Phase 2 obesity trial, New England Journal of Medicine, 26 June 2023</a>. Peer-reviewed original research.</li><li id=\"r3\"><a href=\"https://investor.lilly.com/news-releases/news-release-details/lillys-triple-agonist-retatrutide-delivered-powerful-weight-loss\" rel=\"noopener noreferrer\">Lilly: TRIUMPH-1 topline results, 21 May 2026</a>. Manufacturer report.</li><li id=\"r4\"><a href=\"https://investor.lilly.com/news-releases/news-release-details/lillys-triple-agonist-retatrutide-drove-substantial-improvements\" rel=\"noopener noreferrer\">Lilly: additional TRIUMPH-1 and TRANSCEND-T2D-1 findings, 6 June 2026</a>. Manufacturer report.</li><li id=\"r5\"><a href=\"https://investor.lilly.com/news-releases/news-release-details/lillys-triple-agonist-retatrutide-successful-two-additional\" rel=\"noopener noreferrer\">Lilly: TRIUMPH-2 and TRIUMPH-3 topline results and US submission plan, 23 July 2026</a>. Manufacturer report.</li><li id=\"r6\"><a href=\"https://www.lilly.com/news/stories/what-to-know-about-retatrutide\" rel=\"noopener noreferrer\">Lilly: retatrutide mechanism and terminology explainer, reviewed July 2026</a>. Developer information.</li><li id=\"r7\"><a href=\"https://www.nhs.uk/conditions/overweight-and-obesity/\" rel=\"noopener noreferrer\">NHS: overweight and obesity overview</a>. General UK care information.</li><li id=\"r8\"><span id=\"r9\"></span><span><a href=\"https://investor.lilly.com/news-releases/news-release-details/lilly-present-new-data-foundayo-retatrutide-and-eloratzp-easd\" rel=\"noopener noreferrer\">Lilly: EASD presentation announcement, 15 September 2026</a>. Future presentation notice at the source-check date.</li></ol></details><p class=\"rr-small\">Written and researched by <a href=\"/authors/matt-obrien\">Matt O’Brien</a>, founder of Shift Some Timber. Source checking is not independent clinical approval. <a href=\"/clinical-governance\">How we govern health content</a>.</p></section></div></main>";
