const SCRIPT="\n(()=>{const root=document.getElementById('main-chart');const heading=document.getElementById('analysis-heading');const note=document.getElementById('analysis-note');const buttons=[...document.querySelectorAll('[data-analysis]')];const data={treatment:{values:__TREATMENT__,heading:'Treatment-regimen analysis · peer-reviewed',note:'Includes outcomes regardless of adherence or use of prohibited weight-management treatments. Trial averages are not a personal forecast.'},efficacy:{values:__EFFICACY__,heading:'Efficacy analysis · sponsor-reported',note:'Estimates outcomes with continued study treatment and without prohibited weight-management treatments. This is a different analysis of the same trial, not a better result for the same question.'}};buttons.forEach(button=>button.addEventListener('click',()=>{const key=button.dataset.analysis;const d=data[key];const svg=root.querySelector('svg');const rects=svg.querySelectorAll('rect');const values=svg.querySelectorAll('.rr-bar-value');rects.forEach((rect,i)=>{rect.setAttribute('width',String(d.values[i]*17.5));values[i].setAttribute('x',String(40+d.values[i]*17.5+9));values[i].textContent=d.values[i].toFixed(1)+'%';});svg.setAttribute('aria-label','TRIUMPH-1 '+key+' analysis at 80 weeks');svg.querySelector('title').textContent='TRIUMPH-1 '+key+' analysis at 80 weeks';svg.querySelector('desc').textContent='Average body-weight reduction: retatrutide 12 mg research group '+d.values[0].toFixed(1)+'%; placebo '+d.values[1].toFixed(1)+'%. Adults without diabetes. Research-group identifier, not dosing advice.';heading.textContent=d.heading;note.textContent=d.note;buttons.forEach(b=>b.setAttribute('aria-pressed',String(b===button)));}));})();\n";
